# The kings and princes of Wales, kingdom by kingdom. build.py turns this into kings.html
# (all of Wales) and one kings-<id>.html page per kingdom.
# House rules (see EDITORIAL.md): proud voice, nothing negative about the rulers, Arthur is
# Athrwys ap Meurig "in Welsh tradition", contested points in the tradition's own words.
# For the earliest kings the old genealogies are the only witness, so their dates are estimates
# and marked "c.". Every line has English and Welsh.
#
# A ruler:  R(sort_year, "dates", "name", "note EN", "note CY", link)   link = "person-x.html" etc.
# A heading inside a list:  H("English", "Cymraeg")
# A short note between rulers:  N("English", "Cymraeg")


def R(y, dates, name, en="", cy="", link=None, key=False):
    return dict(k="r", y=y, dates=dates, name=name, en=en, cy=cy, link=link, key=key or bool(link and link.startswith("person-")))


def H(en, cy):
    return dict(k="h", en=en, cy=cy)


def N(en, cy):
    return dict(k="n", en=en, cy=cy)


P = lambda s: f"person-{s}.html"  # noqa: E731

ATHRWYS_EN = "Welsh tradition holds that this king of Gwent and Glywysing was Arthur, whose court was at Caerleon. Other historians may see it differently."
